import os,sys
R=int(sys.argv[2]); svc=sys.argv[1]
def get(rel):
    for n in range(R+1,1000):
        p=f'/app/config-history/r{n:04d}/prev/{rel}'
        if os.path.exists(p): return open(p).read()
    return open('/app/config/'+rel).read()
def run(text,base,cfg,name,svcfile=False):
    sec=None
    for l in text.splitlines():
        l=l.strip()
        if not l or l.startswith('#'): continue
        if l.startswith('['): sec=l[1:-1].strip(); continue
        k,_,v=l.partition('='); k=k.strip(); v=v.strip()
        if k=='include':
            if sec is not None: continue
            v=v.replace('${env}','prod-b').replace('${host}','app-07')
            if svcfile:
                t=os.path.normpath(os.path.join('/app/services/x',v)); rel=os.path.relpath(t,'/app/config')
            else:
                rel=os.path.relpath(os.path.normpath(os.path.join(base,v)),'/app/config')
            print('inc',rel,file=sys.stderr)
            run(get(rel),os.path.dirname('/app/config/'+rel),cfg,name)
        elif svcfile or sec is None or sec==name: cfg[k]=v
cfg={}
run(open(f'/app/services/{svc}/service.conf').read(),None,cfg,svc,True)
print(cfg)
